First, the Levenshtein distance function:
```javascript
function levenshteinDistance(a, b) {
  const m = a.length;
  const n = b.length;
  const dp = Array(m + 1).fill(null).map(() => Array(n + 1).fill(0));

  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (a[i-1] === b[j-1]) {
        dp[i][j] = dp[i-1][j-1];
      } else {
        dp[i][j] = 1 + Math.min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]);
      }
    }
  }

  return dp[m][n];
}
```

Now, the `createDebugHelper` function:
```javascript
function createDebugHelper(viewModel) {
  const availableProperties = Object.keys(viewModel).sort();

  return {
    diagnoseMissingProperty(propertyName) {
      const isAvailable = availableProperties.includes(propertyName);

      if (isAvailable) {
        // Property exists, no error
        return {
          error: false,
          missingProperty: null,
          availableProperties,
          suggestion: null
        };
      }

      // Find closest match using Levenshtein distance
      let closestMatch = null;
      let minDistance = Infinity;

      for (const prop of availableProperties) {
        const distance = levenshteinDistance(propertyName, prop);
        if (distance <= 3) {
          if (distance < minDistance || (distance === minDistance && prop < closestMatch)) {
            minDistance = distance;
            closestMatch = prop;
          }
        }
      }

      return {
        error: true,
        missingProperty: propertyName,
        availableProperties,
        suggestion: closestMatch
      };
    }
  };
}
```

